<?php declare(strict_types=1);
if(!$s['history'])return;
$segmentHistory=array_reverse($s['history']);$historyPages=(int)ceil(count($segmentHistory)/20);$historyRaw=input($_GET,'segment_history_page','1');$historyValid=preg_match('/\A[1-9][0-9]{0,2}\z/D',$historyRaw)&&(int)$historyRaw<=$historyPages;$historyPage=$historyValid?(int)$historyRaw:1;
$historyUrl=static fn(int$page):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'segments'=>'1','segment_history_page'=>(string)$page]);
?>
<details class="card" data-balance-segment-history <?= array_key_exists('segment_history_page',$_GET)?'open':'' ?>><summary><?= e($segmentText('Entscheidungen zur Bereichsaufteilung')) ?> (<?= count($segmentHistory) ?>)</summary>
<?php if(!$historyValid): ?><p role="alert"><?= e($segmentText('Verlaufsseite der Bereichsaufteilung vollständig auswählen.')) ?></p><a class="btn btn-outline" href="<?= e($historyUrl(1)) ?>"><?= e($segmentText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach(array_slice($segmentHistory,($historyPage-1)*20,20)as$h): ?><article><h3><?= e((new DateTimeImmutable($h['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$segmentText($h['state']==='reviewed'?'Bestätigt':'Vorbereitet')) ?></h3><p><?= e($h['note']) ?></p><a class="btn btn-outline" data-balance-segment-history-link="<?= (int)$h['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'segments'=>'1','segment_original'=>(string)$h['revision'],'segment_original_sha256'=>$h['sha256']])) ?>"><?= e($segmentText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($historyPages>1): ?><nav aria-label="<?= e($segmentText('Verlauf der Bereichsaufteilung')) ?>"><p><?= e($segmentText('Seite')) ?> <?= $historyPage ?> / <?= $historyPages ?></p><?php if($historyPage>1): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage-1)) ?>"><?= e($segmentText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($historyPage<$historyPages): ?><a class="btn btn-outline" href="<?= e($historyUrl($historyPage+1)) ?>"><?= e($segmentText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?>
<?php endif ?></details>
